nfs4_sharedfh_t * sfh4_put ( const nfs_fh4 * fh , mntinfo4_t * mi , nfs4_sharedfh_t * key ) { nfs4_sharedfh_t * sfh , * nsfh ; avl_index_t where ; nfs4_sharedfh_t skey ; if ( ! key ) { skey . sfh_fh = * fh ; key = & skey ; } nsfh = kmem_alloc ( sizeof ( nfs4_sharedfh_t ) , KM_SLEEP ) ; nsfh -> sfh_fh . nfs_fh4_len = fh -> nfs_fh4_len ; nsfh -> sfh_fh . nfs_fh4_val = kmem_alloc ( NFS4_FHSIZE , KM_SLEEP ) ; bcopy ( fh -> nfs_fh4_val , nsfh -> sfh_fh . nfs_fh4_val , fh -> nfs_fh4_len ) ; mutex_init ( & nsfh -> sfh_lock , NULL , MUTEX_DEFAULT , NULL ) ; nsfh -> sfh_refcnt = 1 ; nsfh -> sfh_flags = SFH4_IN_TREE ; nsfh -> sfh_mi = mi ; NFS4_DEBUG ( nfs4_sharedfh_debug , ( CE_NOTE , "sfh4_get: new object (%p)" , ( void * ) nsfh ) ) ; ( void ) nfs_rw_enter_sig ( & mi -> mi_fh_lock , RW_WRITER , 0 ) ; sfh = avl_find ( & mi -> mi_filehandles , key , & where ) ; avl_insert ( & mi -> mi_filehandles , nsfh , where ) ; nfs_rw_exit ( & mi -> mi_fh_lock ) ; return ( nsfh ) ; } 